'use strict';

const fs = require('fs');
const path = require('path');

const DEFAULTS = {
  port: 3000,
  host: '127.0.0.1',
};

const INPUT_FILE = path.join(__dirname, 'config.json');
const OUTPUT_FILE = path.join(__dirname, 'config.out.json');

function loadConfig(file) {
  if (!fs.existsSync(file)) return {};
  const raw = fs.readFileSync(file, 'utf8').trim();
  if (!raw) return {};
