'use strict';

const nodeRequire = typeof require === 'function' ? require : null;

const DEFAULTS = {
  port: 3000,
  host: '127.0.0.1',
};

async function loadModule(name) {
  if (nodeRequire) return nodeRequire(name);
  return await import(name);
}

async function main() {
  const fs = await loadModule('node:fs');
  const path = await loadModule('node:path');

  const dir = path.dirname(path.resolve(process.argv[1] || 'check.js'));
  const inputFile = path.join(dir, 'config.json');
  const outputFile = path.join(dir, 'config.out.json');

  const config = readConfig(fs, path, inputFile);
  const merged = withDefaults(config);

  fs.writeFileSync(outputFile, `${JSON.stringify(merged, null, 2)}\n`);

  const written = JSON.parse(fs.readFileSync(outputFile, 'utf8'));
  for (const [key, expected] of Object.entries(DEFAULTS)) {
    if (config[key] === undefined && written[key] !== expected) {
      throw new Error(`verify failed: ${key} is ${written[key]}, expected ${expected}`);
    }
  }

  console.log(`wrote ${path.basename(outputFile)}: ${JSON.stringify(written)}`);
  return written;
}

function readConfig(fs, path, file) {
  if (!fs.existsSync(file)) return {};
  const raw = fs.readFileSync(file, 'utf8').trim();
  if (!raw) return {};
  const parsed = JSON.parse(raw);
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error(`${path.basename(file)} must contain a JSON object`);
  }
  return parsed;
}

function withDefaults(config) {
  const result = {};
  for (const [key, fallback] of Object.entries(DEFAULTS)) {
    const value = config[key];
    result[key] = value === undefined || value === null ? fallback : value;
  }
  for (const [key, value] of Object.entries(config)) {
    if (!(key in result)) result[key] = value;
  }
  return result;
}

main().catch((err) => {
  console.error(`check failed: ${err.message}`);
  process.exit(1);
});

